import {sourceSummary} from './airspace-info.js';
import {initAirspace,enableAirspace,airSearch,chooseAir,screenAirspace} from './airspace.js';
import {createPointLayer} from './canvas-map.js';
import {cards,bars,coverChart,cityStats,summaryStats} from './charts.js';
import {number as num,percent as pct,escapeHTML as e,csvText,labels,nodeColors} from './core.js';
const $=s=>document.querySelector(s),$$=s=>document.querySelectorAll(s);
const titles={airspace:'空域速查',planning:'低空物流规划',comparison:'覆盖对比',analysis:'数据分析',methods:'数据与方法'};
const worker=new Worker(new URL('./data-worker.js',import.meta.url),{type:'module'}),pending=new Map();let requestId=0;
function rpc(method,args={}){return new Promise((resolve,reject)=>{const id=++requestId;pending.set(id,{resolve,reject});worker.postMessage({id,method,args})})}
worker.onmessage=({data})=>{const p=pending.get(data.id);if(!p)return;pending.delete(data.id);data.error?p.reject(Error(data.error)):p.resolve(data.result)};
worker.onerror=event=>{for(const p of pending.values())p.reject(Error(event.message||'数据线程异常'));pending.clear();showError(Error('数据线程异常，请刷新页面重试。'))};
let index,mode='airspace',selectedCity=null,cityReady=false,scenario='all',planMode='network',lastRender=null,selectedDetail=null,renderToken=0,cityToken=0,searchToken=0,renderTimer,methodsLoaded=false,retryAction=null;
const map=L.map('map',{zoomControl:false,preferCanvas:true,minZoom:2,maxZoom:18}).setView([35.5,104.2],4);
const tiles=L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> contributors'}).addTo(map);let tileFailures=0;tiles.on('tileerror',()=>{if(++tileFailures===4)toast('部分底图无法加载；研究数据图层仍可使用，请检查网络。')});L.control.scale({position:'bottomleft',imperial:false}).addTo(map);
initAirspace(map);
const points=createPointLayer(map,selectPoint),highlight=L.layerGroup().addTo(map),radiusLayer=L.layerGroup().addTo(map);
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,5000)}
function busy(text){$('#busy').hidden=!text;if(text)$('#busy-text').textContent=text}
function showError(error,retry){if(error.message==='AbortError')return;$('#error-message').textContent=error.message;$('#error-panel').hidden=false;retryAction=retry||(()=>location.reload());busy(null)}
function clearError(){$('#error-panel').hidden=true}
$('#retry-load').onclick=()=>{clearError();retryAction?.()};
function optionHTML(values,all){return `<option value="">${all}</option>`+values.map(v=>`<option value="${e(v)}">${e(v)}</option>`).join('')}
function populateCities(){const p=$('#province').value;$('#city-select').innerHTML='<option value="">'+(p?'全省概览':'全国概览')+'</option>'+index.cities.filter(s=>!p||s.省份===p).map(s=>`<option value="${s.id}">${e(s.地级市)}</option>`).join('');$('#city-select').value=selectedCity?.id||''}
function currentCities(){return selectedCity?[selectedCity]:index.cities.filter(s=>!$('#province').value||s.省份===$('#province').value)}
function scopeStats(){return selectedCity?cityStats(selectedCity):summaryStats(currentCities())}
function scopeName(){return selectedCity?.地级市||$('#province').value||'全国'}
function filters(){return{province:$('#province').value,type:$('#demand-type').value,intensity:cityReady?$('#intensity').value:0,levels:[...$$('[data-level]:checked')].map(i=>i.dataset.level),nodeKind:$('#node-kind').value,review:cityReady?$('#land-review').value:'',land:cityReady?$('#land-type').value:'',status:cityReady?$('#node-status').value:'',scenario:mode==='comparison'?scenario:'all',showDemand:$('#show-demand').checked,exportKind:$('#export-kind').value}}
function view(){const b=map.getBounds();return{zoom:map.getZoom(),bounds:[b.getWest(),b.getSouth(),b.getEast(),b.getNorth()]}}
function stateURL(){const p=new URLSearchParams();p.set('mode',mode);if(selectedCity)p.set('city',selectedCity.id);else if($('#province').value)p.set('province',$('#province').value);if(planMode!=='network')p.set('plan',planMode);if(scenario!=='all')p.set('scenario',scenario);p.set('layers',filters().levels.join(','));if(!$('#show-demand').checked)p.set('demand','0');if($('#overlay-air').checked)p.set('air','1');if($('#node-kind').value!=='all')p.set('nodes',$('#node-kind').value);if($('#demand-type').value)p.set('type',$('#demand-type').value);history.replaceState(null,'','#'+p.toString())}
async function selectCity(id,{fit=true}={}){
 const token=++cityToken;renderToken++;cityReady=false;clearHighlight();points.setData([]);clearError();selectedCity=index.cities.find(s=>s.id===id)||null;
 if(selectedCity){$('#province').value=selectedCity.省份;populateCities();$('#map-city').textContent=selectedCity.地级市;if(fit&&selectedCity.bounds){const b=selectedCity.bounds;map.fitBounds([[b[1],b[0]],[b[3],b[2]]],{padding:[60,60],maxZoom:11})}
  busy('正在读取 '+selectedCity.地级市+' 的完整规划网络…');try{const result=await rpc('loadCity',{id:selectedCity.id,path:selectedCity.path});if(token!==cityToken)return;cityReady=true;$('#demand-type').innerHTML=optionHTML(result.types,'全部物流类型');$('#land-type').innerHTML=optionHTML(result.lands,'全部土地类别');$('#node-status').innerHTML=optionHTML(result.statuses,'全部模型状态');$('#load-status').textContent=selectedCity.地级市+' · '+num(selectedCity.n_candidates)+' 个需求点';}catch(err){if(token===cityToken)showError(err,()=>selectCity(id));return}finally{if(token===cityToken)busy(null)}
 }else{await rpc('cancel');if(token!==cityToken)return;populateCities();$('#demand-type').innerHTML=optionHTML(Object.keys(index.stats.types),'全部物流类型');$('#map-city').textContent=scopeName()+'概览';$('#load-status').textContent=num(currentCities().length)+' 地区 · 已验证数据';if(fit){const cs=currentCities().filter(s=>s.center);if($('#province').value&&cs.length)map.fitBounds(cs.map(s=>s.center),{padding:[45,45],maxZoom:8});else map.setView([35.5,104.2],4)}}
 for(const id of ['intensity','land-review','land-type','node-status'])$('#'+id).disabled=!cityReady;$('#city-filter-hint').hidden=cityReady;$('#export-data').disabled=!cityReady;$('#export-viewport').disabled=!cityReady;
 $('#global-results').replaceChildren();$('#global-search').value='';updateScopeUI();await renderMap();stateURL();
}
function updateScopeUI(){if(!index)return;const s=scopeStats();$('#comparison-location').textContent=scopeName();$('#comparison-values').innerHTML=`原模型 ${pct(s.point_coverage)}<br>规划模型 ${pct(s.planning_point_coverage)}`;if(mode==='analysis')renderAnalysis();if(mode==='comparison'){$('#comparison-summary').innerHTML='<h3>'+e(scopeName())+' · 全量情景对比</h3>'+coverChart(s)+'<p class="tiny muted">新增完整路径 '+num(s.planning_covered-s.baseline_covered)+' 个；虚拟 DZ / LD / DC：'+num(s.virtual.DZ)+' / '+num(s.virtual.LD)+' / '+num(s.virtual.DC)+'</p>';}}
function renderMapStats(s){$('#map-stats').innerHTML=[['筛选需求',num(s.demand_points)],['原模型覆盖',pct(s.point_coverage)],['筛选虚拟',num(s.virtual_total)]].map(([name,value])=>`<div><span>${name}</span><strong>${value}</strong></div>`).join('')}
async function setMode(next){if(!titles[next])return;renderToken++;mode=next;clearHighlight();clearError();document.body.className=next+'-mode';$$('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===mode);b.setAttribute('aria-current',b.dataset.mode===mode?'page':'false')});$('#mode-title').textContent=titles[mode];$('#air-panel').hidden=mode!=='airspace';$('#planning-panel').hidden=!['planning','comparison'].includes(mode);$('#analysis-panel').hidden=mode!=='analysis';$('#methods-panel').hidden=mode!=='methods';$('#comparison-bar').hidden=mode!=='comparison';$('#comparison-summary').hidden=mode!=='comparison';updateScopeUI();$('#map-stats').hidden=!['planning','comparison'].includes(mode);$('#legend').hidden=mode!=='airspace';$('#planning-legend').hidden=mode==='airspace';$('#map-mode').textContent=titles[mode];$('#map-disclaimer').textContent=mode==='airspace'?'收录空域 · 未核验现行状态':'模型规划位置 · 未验证建设及运营条件';
 enableAirspace(mode==='airspace'||($('#overlay-air').checked&&['planning','comparison'].includes(mode)));
 if(mode==='comparison'){$('#show-demand').checked=true;$$('[data-level]').forEach(i=>i.checked=false)}
 if(mode==='airspace'||mode==='analysis'||mode==='methods')points.setData([]);if(mode==='methods')await renderMethods();else if(mode==='analysis')renderAnalysis();else await renderMap();stateURL();setTimeout(()=>map.invalidateSize(),0);
}
async function renderMap(){
 if(!index||!['planning','comparison'].includes(mode))return;if(selectedCity&&!cityReady)return;const token=++renderToken;
 try{if(!selectedCity)await rpc('overview');const result=await rpc('render',{filters:filters(),view:view(),city:cityReady});if(token!==renderToken)return;lastRender=result;points.setData(result.points,$('#render-mode').value);$('#filtered-count').textContent=num(result.metrics.demand_points)+' 需求';const s=result.metrics;$('#filtered-summary').innerHTML=[['需求点',num(s.demand_points)],['原覆盖 / 点数',pct(s.point_coverage)],['筛选节点',num(Object.values(s.nodes).reduce((a,b)=>a+b,0))],['新增虚拟',num(s.virtual_total)]].map(([a,b])=>`<div><span>${a}</span><strong>${b}</strong></div>`).join('');$('#viewport-summary').textContent=result.national?'全国为精确汇总的空间网格；节点以所属地区聚合显示，点击进入地区。':`当前视野：${num(result.viewportMetrics.demand_points)} 个需求点、${num(Object.values(result.viewportMetrics.nodes).reduce((a,b)=>a+b,0))} 个筛选节点。`;renderMapStats(s);$('#map-hint').textContent=result.national?'全国聚合分布 · 点击进入地区':map.getZoom()<13?'点击聚合点放大 · 高缩放级别显示单点':'点击需求 / 节点追踪规划路径';renderObjectList(result);
 }catch(err){if(token===renderToken)showError(err,renderMap)}
}
function renderObjectList(r){const target=$('#object-list');if(r.national){target.innerHTML='<p class="empty">选择地区后查看完整对象与原始字段。</p>';return}target.innerHTML=(r.list||[]).map(v=>`<button class="region-card" data-object="${e(v.id)}"><strong>${e(v.name)}</strong><p>${e(v.level)} · ${v.virtual?'虚拟规划':'模型记录'} · 权重 ${num(v.weight)}</p></button>`).join('')+(r.listTotal>60?`<p class="tiny muted">列表显示前 60 条；完整 ${num(r.listTotal)} 条可按当前筛选导出。</p>`:'');if(!r.list?.length)target.innerHTML='<p class="empty">当前条件没有记录。请调整筛选。</p>';target.querySelectorAll('[data-object]').forEach(b=>b.onclick=()=>openDetail(b.dataset.object))}
function selectPoint(p){if(p.city){selectCity(p.city);return}if(p.aggregate&&p.count>1){map.setView([p.lat,p.lng],Math.min(18,map.getZoom()+2));return}openDetail(p.id)}
function clearHighlight(){openDetail.sequence++;highlight.clearLayers();radiusLayer.clearLayers();selectedDetail=null;$('#node-detail').hidden=true}
function relationHTML(edge,down=false){const id=down?edge.child:edge.parent;return `<div class="detail-row"><button data-related="${e(id)}">${e(edge.child.split('|').at(-1))} → ${e(edge.parent.split('|').at(-1))} ↗</button><small>${num(edge.distance)} m / 约束 ${num(edge.radius)} m · ${edge.action==='preserved'?'原连接保留':edge.action==='reuse_in_planning'?'规划复用':'规划新增'}</small></div>`}
async function openDetail(id){
 const token=cityToken,requested=++openDetail.sequence;try{const d=await rpc('detail',{id});if(!cityReady||token!==cityToken||requested!==openDetail.sequence)return;clearHighlight();selectedDetail=d;closeMobile();const r=d.row;
  const bounds=[];for(const edge of [...d.up,...d.down]){const line=L.polyline(edge.points,{color:edge.action==='preserved'?'#348975':'#d99734',weight:2.3,opacity:.8,dashArray:edge.action==='preserved'?null:'7 5'}).addTo(highlight);bounds.push(...edge.points);line.bindTooltip(`${edge.action} · ${num(edge.distance)} m`)}
  L.circleMarker([r.纬度,r.经度],{radius:9,color:'#fff',weight:3,fillColor:'#143e31',fillOpacity:1}).addTo(highlight);map.panTo([r.纬度,r.经度]);drawRadius();const air=screenAirspace(r.经度,r.纬度);
  const panel=$('#node-detail');panel.hidden=false;panel.innerHTML=`<button class="close-button" id="close-node" aria-label="关闭对象详情">×</button><span class="badge ${r.is_virtual_plan?'virtual':''}">${d.kind==='demand'?'物流需求点':e(labels[r.层级])+' · '+(r.is_virtual_plan?'新增虚拟':'模型非新增')}</span><h2>${e(r.名称||r.中心ID.split('|').at(-1))}</h2>${d.kind==='node'?'<div class="notice">模型规划位置｜未验证建设及运营条件</div>':''}<dl><dt>地区</dt><dd>${e(r.城市Key)}</dd><dt>记录 ID</dt><dd>${e(d.id)}</dd><dt>经纬度</dt><dd>${Number(r.经度).toFixed(6)}°, ${Number(r.纬度).toFixed(6)}°</dd><dt>需求权重</dt><dd>${num(r.规模权重??r.簇权重总和)}</dd><dt>土地类型</dt><dd>${e(r.landuse_name||'未提供')}</dd>${d.kind==='demand'?`<dt>原模型完整路径</dt><dd>${d.state.baseline_complete_path?'已覆盖':'未覆盖'}</dd><dt>规划完整路径</dt><dd>${d.state.planning_complete_path?'已覆盖':'未覆盖'}</dd><dt>需求得分</dt><dd>${num(r.需求得分)}</dd>`:`<dt>建设核验</dt><dd>${r.construction_verified===true?'原字段为 True（仍需核验）':'未验证'}</dd><dt>土地核查</dt><dd>${r.land_review==='needs_review'?'土地待核查':'仅分类信息，不代表许可'}</dd><dt>服务半径</dt><dd>${num(d.radius)} m</dd><dt>节点来源</dt><dd>${e(r.coverage_node_origin||'未提供')}</dd>`}</dl>${r.land_evidence?`<p class="tiny muted">土地证据：${e(r.land_evidence)}</p>`:''}${r.needs_function_capacity_land_confirmation?'<p class="notice">现实功能、处理容量与土地条件仍需确认。</p>':''}<div class="${air.hits.length?'danger-note':'notice'}"><strong>空域初步筛查</strong><br>${!air.loaded?'空域数据尚未加载，暂无法判断。':air.hits.length?`命中 ${air.hits.length} 个收录边界：${air.hits.slice(0,5).map(v=>e(v.name)+'（'+e(v.level)+'）').join('、')}`:'未命中当前收录边界，不代表可飞。'}<br>原坐标基准尚未独立确认；此结果不代表飞行许可或官方审批。</div><h3>规划情景 · 上级路径</h3>${d.up.length?d.up.map(v=>relationHTML(v)).join(''):'<p class="tiny muted">当前对象没有更上级节点。</p>'}<h3>直接下级 · ${num(d.downTotal)}</h3>${d.down.map(v=>relationHTML(v,true)).join('')}${d.downTotal>200?'<p class="tiny muted">为避免线团，显示前 200 条直接下级连接。可导出全部直接关联。</p>':''}<button class="secondary wide" id="export-relations">↓ 导出全部直接关联 CSV</button>${d.facility?`<h3>模型共址位置</h3><p class="tiny muted">${e(d.facility.facility_id)}<br>共 ${num(d.members.length)} 个模型节点，不是已建成设施数量。</p>${d.members.slice(0,20).map(id=>`<button class="secondary" data-related="${e(id)}">${e(id.split('|').at(-1))}</button>`).join('')}`:''}${d.poi?'<h3>周边 POI 结构</h3><div class="poi-tabs"><button data-poi="300">300 米</button><button data-poi="500">500 米</button></div><div id="poi-chart"></div><p class="tiny muted">统计邻域 POI 数量，不表示实际设施能力。</p>':''}<details class="raw-fields"><summary>展开完整数据字段</summary><table>${Object.entries({...r,...(d.state||{})}).map(([k,v])=>`<tr><td>${e(k)}</td><td>${e(v==null?'未提供':v)}</td></tr>`).join('')}</table></details>`;
  panel.scrollTop=0;$('#close-node').onclick=clearHighlight;panel.querySelectorAll('[data-related]').forEach(b=>b.onclick=()=>openDetail(b.dataset.related));$('#export-relations').onclick=()=>exportData('relations',d.id);panel.querySelectorAll('[data-poi]').forEach(b=>b.onclick=()=>renderPOI(d.poi,b.dataset.poi));if(d.poi)renderPOI(d.poi,'300');
 }catch(err){toast(err.message)}
}
openDetail.sequence=0;
function renderPOI(poi,radius){$('#poi-chart').innerHTML=bars(Object.entries(poi).filter(([k])=>k.startsWith(radius+'m_')&&k.includes('数量')).map(([k,v])=>({name:k.replace(radius+'m_邻域','').replace('数量',''),value:v||0})));}
function drawRadius(){radiusLayer.clearLayers();if($('#radius-toggle').checked&&selectedDetail?.radius){const r=selectedDetail.row;L.circle([r.纬度,r.经度],{radius:selectedDetail.radius,color:'#318f7c',weight:1.5,dashArray:'5 6',fillOpacity:.07}).addTo(radiusLayer).bindTooltip(`模型半径 ${num(selectedDetail.radius)} m；不是可飞区域`)}}
function download(content,name,type='text/csv;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function exportData(kind=$('#export-kind').value,id=null){if(!cityReady){toast('请选择一个地区，再导出原始对象记录。');return}try{busy('正在整理导出数据…');const r=await rpc('export',{filters:filters(),kind,id,viewport:$('#export-viewport').checked?view().bounds:null});download(r.csv,`${scopeName()}-${kind}.csv`);toast(`已导出 ${num(r.count)} 条记录。`)}catch(err){toast(err.message)}finally{busy(null)}}
function renderAnalysis(){
 if(!index)return;const cs=currentCities(),s=scopeStats(),panel=$('#analysis-panel'),rank=(field)=>index.cities.filter(c=>!$('#province').value||c.省份===$('#province').value).sort((a,b)=>b[field]-a[field]).slice(0,10).map(c=>({name:c.地级市,value:c[field],action:'city:'+c.id}));
 panel.innerHTML=`<div class="toolbar"><div><div class="eyebrow">RESEARCH / ANALYTICS</div><h2>${e(scopeName())} · 规划数据分析</h2></div><button id="export-stats">↓ 地区指标 CSV</button></div><p class="lead">原模型与虚拟节点规划情景的完整路径覆盖。所有比例按对应分母计算，点数与需求权重分别展示。</p><div class="scope-note">统计范围：${e(scopeName())}，${num(cs.length)} 个地区。以下为地区全量模型指标；地图对象筛选结果在地图侧栏单独显示。</div>${cards(s)}<div class="chart-grid"><article class="chart-card"><h3>原模型与规划情景</h3><p>完整路径：需求点 → DZ → LD → DC</p>${coverChart(s)}</article><article class="chart-card"><h3>三级模型节点结构</h3><p>点击层级切换至地图。共址模型节点分别计数。</p>${bars(Object.entries(s.nodes).map(([k,v])=>({name:labels[k],value:v,color:nodeColors[k],action:'level:'+k})))}</article><article class="chart-card"><h3>新增虚拟节点</h3><p>模型规划位置，未验证建设及运营条件</p>${bars(Object.entries(s.virtual).map(([k,v])=>({name:'虚拟 '+k,value:v,color:nodeColors[k],action:'virtual:'+k})))}</article><article class="chart-card"><h3>虚拟节点土地核查</h3><p>不透水面仅为分类，不等于建设许可</p>${bars(Object.entries(s.virtualLand).map(([k,v])=>({name:k==='needs_review'?'土地待核查':'仅不透水面分类',value:v,color:k==='needs_review'?'#c8954b':'#669b7c',action:'review:'+k})))}</article><article class="chart-card"><h3>需求类型结构</h3><p>真实需求记录按物流类型计数</p>${bars(Object.entries(s.types).sort((a,b)=>b[1]-a[1]).map(([k,v])=>({name:k,value:v,action:'type:'+k})))}</article><article class="chart-card"><h3>500 米邻域 POI 结构</h3><p>各需求点邻域计数之和，重叠邻域会重复计数；不是独立 POI 总数。</p>${bars(Object.entries(s.poi).filter(([k])=>k.startsWith('500m_')).map(([k,v])=>({name:k.replace('500m_邻域','').replace('数量',''),value:v})))}</article><article class="chart-card"><h3>城市需求规模 · TOP 10</h3><p>点击地区进入地图查看</p>${bars(rank('n_candidates'))}</article><article class="chart-card"><h3>规划新增覆盖需求 · TOP 10</h3><p>规划覆盖点数减原模型覆盖点数</p>${bars(rank('planning_additional_covered_points'))}</article><article class="chart-card"><h3>新增虚拟节点 · TOP 10</h3><p>同一来源只计数一次</p>${bars(index.cities.filter(c=>!$('#province').value||c.省份===$('#province').value).map(c=>({...c,total:c.virtual_DZ+c.virtual_LD+c.virtual_DC})).sort((a,b)=>b.total-a.total).slice(0,10).map(c=>({name:c.地级市,value:c.total,action:'city:'+c.id})))}</article><article class="chart-card"><h3>${selectedCity?'地区人口与距离约束':'研究口径'}</h3>${selectedCity?`<dl class="compare-table"><dt>人口</dt><dd>${num(selectedCity.pop_person)} 人</dd><dt>人口密度</dt><dd>${num(selectedCity.density_pop_per_km2)} 人/km²</dd>${['DZ','LD','DC'].map(l=>`<dt>${l} 模型半径</dt><dd>${num(selectedCity['coverage_radius_'+l+'_km'])} km</dd>`).join('')}<dt>模型共址位置</dt><dd>${num(selectedCity.facilities)} 处</dd></dl>`:'<p class="lead">模型允许新增虚拟节点，没有把预算、容量、土地审批、道路和空域许可全部设为硬约束。规划 100% 覆盖不能解释为 100% 可飞或经济最优。</p>'}<div class="notice">规划剩余空间连接缺口：${num(cs.reduce((a,c)=>a+c.planning_remaining_gaps,0))}。原 uncovered.csv 为空，没有生成缺口记录。</div></article></div><article class="chart-card" style="margin-top:18px"><h3>两地区横向比较</h3><div class="compare-selector"><select id="compare-a" aria-label="比较地区一">${index.cities.map(c=>`<option value="${c.id}">${e(c.省份+' / '+c.地级市)}</option>`).join('')}</select><select id="compare-b" aria-label="比较地区二">${index.cities.map(c=>`<option value="${c.id}">${e(c.省份+' / '+c.地级市)}</option>`).join('')}</select></div><div id="city-comparison"></div></article>`;
 const chengdu=index.cities.find(c=>c.地级市==='成都市'),shenzhen=index.cities.find(c=>c.地级市==='深圳市');$('#compare-a').value=selectedCity?.id||chengdu.id;$('#compare-b').value=shenzhen.id;$('#compare-a').onchange=$('#compare-b').onchange=renderCityComparison;renderCityComparison();panel.querySelectorAll('[data-chart-action]').forEach(b=>b.onclick=()=>chartAction(b.dataset.chartAction));$('#export-stats').onclick=()=>{const cols=['城市Key','n_candidates','baseline_covered_points','baseline_weight_coverage','planning_covered_points','planning_weight_coverage','virtual_DZ','virtual_LD','virtual_DC','coverage_radius_DZ_km','coverage_radius_LD_km','coverage_radius_DC_km'];download(csvText(cs,cols),scopeName()+'-地区统计.csv')};
}
function renderCityComparison(){const a=index.cities.find(c=>c.id===$('#compare-a').value),b=index.cities.find(c=>c.id===$('#compare-b').value);const rows=[['需求点',c=>num(c.n_candidates)],['原覆盖 / 点数',c=>pct(c.n_candidates?c.baseline_covered_points/c.n_candidates:null)],['原覆盖 / 权重',c=>pct(c.baseline_weight_coverage)],['规划覆盖 / 点数',c=>pct(c.n_candidates?c.planning_covered_points/c.n_candidates:null)],['规划覆盖 / 权重',c=>pct(c.planning_weight_coverage)],['新增覆盖点',c=>num(c.planning_additional_covered_points)],...['DZ','LD','DC'].map(l=>['虚拟 '+l,c=>num(c['virtual_'+l])]),...['DZ','LD','DC'].map(l=>[l+' 半径（km）',c=>num(c['coverage_radius_'+l+'_km'])]),['人口',c=>num(c.pop_person)],['土地待核查虚拟',c=>num(c.virtualLand.needs_review||0)]];$('#city-comparison').innerHTML=`<table class="compare-table"><thead><tr><th>指标</th><th>${e(a.地级市)}</th><th>${e(b.地级市)}</th></tr></thead><tbody>${rows.map(([label,fn])=>`<tr><td>${label}</td><td>${fn(a)}</td><td>${fn(b)}</td></tr>`).join('')}</tbody></table>`}
async function chartAction(action){const pos=action.indexOf(':'),type=action.slice(0,pos),value=action.slice(pos+1);if(type==='city'){await selectCity(value);await setMode('planning');resetFilters();return}await setMode('planning');if(type==='level'||type==='virtual'){$$('[data-level]').forEach(i=>i.checked=i.dataset.level===value);$('#node-kind').value=type==='virtual'?'virtual':'all';$('#show-demand').checked=false;$('#export-kind').value='centers'}if(type==='review'){if(!cityReady){toast('土地状态的逐节点筛选需要选择地区。');return}$('#land-review').value=value;$('#node-kind').value='virtual';$$('[data-level]').forEach(i=>i.checked=true);$('#export-kind').value='centers'}if(type==='type'){$('#demand-type').value=value;$('#show-demand').checked=true}renderMap();stateURL()}
async function renderMethods(){if(methodsLoaded)return;try{const response=await fetch('data/planning/methods.json');if(!response.ok)throw Error('方法文档加载失败');const data=await response.json();const airResponse=await fetch('data/airspace-summary.json');if(!airResponse.ok)throw Error('空域来源说明加载失败');const airMetadata=await airResponse.json();$('#methods-panel').innerHTML=`<div class="eyebrow">DATA / METHODS / LIMITATIONS</div><h2>数据与方法</h2><p class="lead">研究结果的可追溯说明。原始输入、模型假设与现实可实施性分开表达。</p><div class="methods-grid"><div><article class="method-card"><h3>两个独立的数据来源</h3><p>${e(sourceSummary(airMetadata))}</p><p>物流：${e(index.source)}，${num(index.stats.regions)} 地区，${num(index.stats.demand_points)} 个原始需求点。使用已完成的计算结果，网站未重新运行规划模型。</p><code>SHA256 ${e(index.source_sha256)}</code></article><article class="method-card"><h3>需求 → DZ → LD → DC</h3><p>DZ 表示需求服务组；LD、DC 分别为模型的二级、三级网络节点，具体功能以原研究定义为准。节点与模型共址位置分开计数。非新增节点也不等于已建成现实设施。</p><p>保留原成功连接，优先复用；仍有缺口时在模型子节点位置生成候选，采用贪心覆盖与逆向去冗余。没有保证全局最少节点或最低成本。</p></article><article class="method-card"><h3>覆盖与距离口径</h3><p>点数覆盖率 = 完整路径需求点数 ÷ 全部需求点数。权重覆盖率 = 完整路径需求权重 ÷ 全部需求权重。全国加权指标按权重汇总，不平均城市比例。</p><p>半径按每个地区、每个层级读取；距离为原模型投影下的平面距离，不是道路里程、飞行时间或实际航程。服务半径圆是地图距离示意，不是可飞区域。</p><p>原模型只展示完整路径状态与统计；未提供完整历史网络快照，因此不虚构原模型几何。</p></article></div><div><article class="method-card"><h3>坐标与现实条件</h3><div class="notice">物流原始经纬度来源基准未独立确认；保留原值，没有猜测 WGS84、GCJ-02 或 BD-09 转换。空域叠加仅为基于当前数据的初步空间筛查。</div><p>虚拟节点未核验建设与运营条件；不透水面仅为土地分类。预算、容量、土地审批、道路通达与空域许可不是本次完整硬约束。100% 规划空间覆盖不代表现实可行或 100% 可飞。</p><p>POI 图表为各需求点邻域统计之和，邻域重叠会重复计数；不是城市独立 POI 总数。</p></article><article class="method-card"><h3>导入质量检查</h3><p>${num(index.validation.regions)} 个地区通过导入校验；${num(index.validation.links)} 条覆盖连接完成引用、层级和半径检查；无非法经纬度。与 ZIP 内全国汇总表计数一致，未叠加导入根表与城市表。</p><p>centers 与 virtual_nodes 只计一次节点。scenario_comparison 与 city_summary 共用标准化指标。uncovered 表为空，地图不生成虚构缺口。</p><details><summary>研究交付验证记录（原文件自述）</summary>${data.evidence.map(v=>`<pre>${e(v.content)}</pre>`).join('')}</details><details><summary>逐地区独立验证记录</summary><pre>${e(JSON.stringify(index.independent_checks,null,2))}</pre></details></article></div></div><article class="method-card"><h3>原始字段字典</h3><p>每个对象详情可展开完整字段；选定城市后可导出当前筛选的原始字段及覆盖状态。空值保留为未提供。</p>${Object.entries(data.schemas).map(([name,columns])=>`<details><summary>${e(name)} · ${columns.length} 个字段</summary><div class="schema">${columns.map(c=>`<code>${e(c)}</code>`).join('')}</div></details>`).join('')}</article>${data.documents.map((d,i)=>`<article class="method-card"><h3>${i===0?'研究说明原文':'使用与算法说明原文'}</h3><details><summary>展开交付文档</summary><pre>${e(d.content)}</pre></details></article>`).join('')}`;methodsLoaded=true}catch(err){showError(err,renderMethods)}}
async function globalSearch(){const token=++searchToken,q=$('#global-search').value.trim().toLowerCase(),target=$('#global-results');target.replaceChildren();if(!q||!index)return;const cs=index.cities.filter(c=>(c.城市Key+' '+c.地级市).toLowerCase().includes(q));for(const c of cs.slice(0,12)){const b=document.createElement('button');b.textContent=c.省份+' / '+c.地级市+' · '+num(c.n_candidates)+' 需求';b.onclick=()=>{selectCity(c.id);closeMobile()};target.appendChild(b)}const as=airSearch(q);for(const r of as.slice(0,6)){const b=document.createElement('button');b.textContent='空域 · '+r.name;b.onclick=async()=>{await setMode('airspace');chooseAir(r);target.replaceChildren();closeMobile()};target.appendChild(b)}if(cityReady){const objects=await rpc('search',{query:q});if(token!==searchToken)return;for(const o of objects){const b=document.createElement('button');b.textContent=o.level+' · '+o.name;b.onclick=()=>{if(!['planning','comparison'].includes(mode))setMode('planning');openDetail(o.id);target.replaceChildren();closeMobile()};target.appendChild(b)}}else{const cityFromId=index.cities.find(c=>q.startsWith((c.城市Key+'|').toLowerCase()));if(cityFromId){const b=document.createElement('button');b.textContent='在 '+cityFromId.地级市+' 中查找该 ID';b.onclick=async()=>{await selectCity(cityFromId.id);await setMode('planning');const match=await rpc('search',{query:q});if(match.length)openDetail(match[0].id);else toast('该地区未找到这个 ID。')};target.appendChild(b)}}if(!target.children.length)target.innerHTML='<p>未找到匹配。可输入城市、省份或完整节点 ID；地区内也可搜索名称。</p>'}
function closeMobile(){if(innerWidth<=760)$('#workspace').classList.remove('mobile-open')}
function resetFilters(){scenario='all';planMode='network';$('#show-demand').checked=true;$$('[data-level]').forEach(i=>i.checked=i.dataset.level!=='DZ');for(const id of ['demand-type','land-review','land-type','node-status'])$('#'+id).value='';$('#intensity').value='0';$('#node-kind').value='all';$('#render-mode').value='points';$('#export-kind').value='candidates';$$('[data-plan]').forEach(b=>b.classList.toggle('active',b.dataset.plan===planMode));$$('[data-scenario]').forEach(b=>b.classList.toggle('active',b.dataset.scenario===scenario));clearHighlight();renderMap();stateURL()}
$$('[data-mode]').forEach(b=>b.onclick=()=>{setMode(b.dataset.mode);closeMobile()});$$('[data-region]').forEach(b=>b.onclick=()=>{const c=index?.cities.find(c=>c.地级市===b.dataset.region);if(!c)$('#province').value='';selectCity(c?.id);closeMobile()});$('#province').onchange=()=>{selectedCity=null;populateCities();selectCity(null)};$('#city-select').onchange=()=>{selectCity($('#city-select').value);closeMobile()};$('#global-search').oninput=()=>{clearTimeout(globalSearch.timer);globalSearch.timer=setTimeout(globalSearch,180)};$('#global-search').onkeydown=event=>{if(event.key==='Escape')$('#global-results').replaceChildren();if(event.key==='Enter')$('#global-results button')?.click()};
$$('#planning-panel select,#planning-panel input').forEach(i=>i.addEventListener('change',()=>{if(i.id==='radius-toggle'){drawRadius();return}if(i.id==='overlay-air')enableAirspace(i.checked);renderMap();stateURL()}));
$$('[data-plan]').forEach(b=>b.onclick=()=>{planMode=b.dataset.plan;$$('[data-plan]').forEach(x=>x.classList.toggle('active',x===b));$('#node-kind').value=planMode==='virtual'?'virtual':'all';$('#show-demand').checked=planMode==='demand';$$('[data-level]').forEach(i=>i.checked=planMode!=='demand');$('#export-kind').value=planMode==='demand'?'candidates':'centers';renderMap();stateURL()});
$$('[data-scenario]').forEach(b=>b.onclick=()=>{scenario=b.dataset.scenario;$$('[data-scenario]').forEach(x=>x.classList.toggle('active',x===b));renderMap();stateURL()});$('#clear-filters').onclick=resetFilters;$('#clear-highlight').onclick=clearHighlight;$('#radius-toggle').onchange=drawRadius;$('#export-data').onclick=()=>exportData();$('#reset-view').onclick=()=>selectCity(selectedCity?.id);$('#toggle-sidebar').onclick=()=>{const w=$('#workspace');if(innerWidth<=760)w.classList.toggle('mobile-open');else w.classList.toggle('collapsed');$('#toggle-sidebar').setAttribute('aria-expanded',String(innerWidth<=760?w.classList.contains('mobile-open'):!w.classList.contains('collapsed')));setTimeout(()=>map.invalidateSize(),0)};
$$('[data-export-table]').forEach(b=>b.onclick=()=>exportData(b.dataset.exportTable));
$('#share').onclick=async()=>{stateURL();try{await navigator.clipboard.writeText(location.href);toast('当前地区、模式与主要图层的链接已复制。')}catch{toast('请复制浏览器地址栏中的完整网址。')}};
$('#legend-toggle').onclick=()=>{const el=$('#planning-legend .legend-items');el.hidden=!el.hidden;$('#legend-toggle').textContent=el.hidden?'图例 ＋':'图例 −';$('#legend-toggle').setAttribute('aria-expanded',String(!el.hidden))};
map.on('moveend',()=>{clearTimeout(renderTimer);renderTimer=setTimeout(renderMap,100)});
async function init(){const controls=[...$$('.topbar nav button,.quick-cities button'),$('#global-search'),$('#province'),$('#city-select')];controls.forEach(v=>v.disabled=true);busy('正在读取全国统计与地区索引…');try{const response=await fetch('data/planning/index.json');if(!response.ok)throw Error('全国索引加载失败 '+response.status);index=await response.json();await rpc('init',{data:index});$('#province').innerHTML=optionHTML([...new Set(index.cities.map(c=>c.省份))],'全国各省');populateCities();const p=new URLSearchParams(location.hash.slice(1));$('#province').value=p.get('province')||'';planMode=p.get('plan')||'network';scenario=p.get('scenario')||'all';$('#overlay-air').checked=p.get('air')==='1';$('#show-demand').checked=p.get('demand')!=='0';if(p.has('layers'))$$('[data-level]').forEach(i=>i.checked=p.get('layers').split(',').includes(i.dataset.level));$('#node-kind').value=p.get('nodes')||'all';await selectCity(p.get('city'));const wanted=titles[p.get('mode')]?p.get('mode'):'airspace';await setMode(wanted);if(p.get('type'))$('#demand-type').value=p.get('type');$$('[data-plan]').forEach(b=>b.classList.toggle('active',b.dataset.plan===planMode));$$('[data-scenario]').forEach(b=>b.classList.toggle('active',b.dataset.scenario===scenario));renderMap();busy(null)}catch(err){showError(err,init)}finally{controls.forEach(v=>v.disabled=false)}}
init();
